 * 파일기능 : app_id(또는 텍스트) 공유/복사 유틸 (폐쇄망 대응)
 * 작성자   : 차주영
 */

export const fallbackCopy = (text) => {
	try {
		const ta = document.createElement('textarea')
		ta.value = String(text ?? '')
		ta.setAttribute('readonly', '')
		ta.style.position = 'fixed'
		ta.style.top = '-9999px'
		document.body.appendChild(ta)
		ta.select()
		const ok = document.execCommand('copy')
		document.body.removeChild(ta)
		return ok
	} catch (e) {
		return false
	}
}

export const copyAppId = async (appId) => {
	const id = String(appId || '').trim()
	if (!id) return { ok: false, reason: 'EMPTY' }

	try {
		// 폐쇄망/보안환경 고려: secureContext 조건 포함
		if (navigator.clipboard?.writeText && window.isSecureContext) {
			await navigator.clipboard.writeText(id)
			return { ok: true, method: 'clipboard' }
		}

		const ok = fallbackCopy(id)
		return ok ? { ok: true, method: 'execCommand' } : { ok: false, reason: 'COPY_FAILED' }
	} catch (e) {
		return { ok: false, reason: 'ERROR', error: e }
	}
}
